import { getCongTrinh } from "./cong-trinh-data";
import type { GalleryItem } from "@/components/ProductGallery";

/**
 * Resolves a PRODUCT_CATEGORIES `showcase` array into gallery items.
 *
 * Runs on the server only. Pages call this and pass the plain result down to
 * <ProductGallery>, so the 95KB cong-trinh-data library never reaches a client
 * bundle. Any slug that no longer exists is skipped rather than rendering a
 * broken tile — the data file is generated by a script and slugs can be renamed.
 */
export function galleryForShowcase(
  showcase: readonly { slug: string; label: string }[],
  perProject = 2
): GalleryItem[] {
  const items: GalleryItem[] = [];

  for (const entry of showcase) {
    const project = getCongTrinh(entry.slug);
    if (!project) continue;

    const picks = project.images.slice(0, perProject);
    picks.forEach((src, i) => {
      items.push({
        src,
        // Only the first photo carries the curated label; extras are numbered
        // so the caption never claims something the photo does not show.
        label: i === 0 ? entry.label : `${entry.label} — ảnh ${i + 1}`,
        href: `/cong-trinh/${project.slug}`,
      });
    });
  }

  return items;
}
